param([Parameter(Mandatory=$true)][string]$RepoRoot)
Set-StrictMode -Version Latest;$ErrorActionPreference="Stop";function Die([string]$Code,[string]$Detail){throw($Code+":"+$Detail)};$RepoRoot=(Resolve-Path -LiteralPath $RepoRoot).Path;. (Join-Path $RepoRoot "scripts\storage\_lib_ld_receipts_v1.ps1");$script=Join-Path $RepoRoot "scripts\storage\ld_storage03_destination_matrix_v1.ps1";$out=& powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $script -RepoRoot $RepoRoot;if($LASTEXITCODE-ne0){Die "MATRIX_EXIT" ([string]$LASTEXITCODE)};$r=LDREC-ReadReceiptFromOutput $out "ld.device.storage03_destination_matrix.receipt.v1" (Join-Path $RepoRoot "schemas");if(-not[bool]$r.ok){Die "MATRIX_NOT_OK" ""};if([int]$r.verified_destination_count-ne1){Die "VERIFIED_COUNT" ""};if([int]$r.blocked_destination_count-ne3){Die "BLOCKED_COUNT" ""};if([int]$r.unavailable_destination_count-ne2){Die "UNAVAILABLE_COUNT" ""};if(([string]$r.rows[0].status)-ne"verified"){Die "LOCAL_NOT_VERIFIED" ""};if(-not(@($r.rows|Where-Object{([string]$_.destination_class)-eq"unc_network_share" -and [string]$_.status-eq"unavailable"}).Count-eq1)){Die "UNC_STATE" ""};if(-not(@($r.rows|Where-Object{([string]$_.destination_class)-eq"fat32_volume" -and [string]$_.status-eq"unavailable"}).Count-eq1)){Die "FAT32_STATE" ""};Write-Output "PASS: local destination write probe and bounded copy verified";Write-Output "PASS: overlap, repository-root, and missing destinations fail closed";Write-Output "PASS: network-share and FAT32 states are explicitly unavailable, not falsely supported";Write-Output "SELFTEST_LD_STORAGE03_DESTINATION_MATRIX_OK"
